export type PageViewEvent = {
  path: string
  timestamp: number
  userAgent?: string
}

export async function logPageView(event: PageViewEvent): Promise<void> {
  const res = await fetch('https://analytics.example.com/pageview', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(event),
  })

  if (!res.ok) {
    console.error(`[analytics] failed to log page view: ${res.status}`)
  }
}

import { after, headers } from 'next/server'
import { logPageView } from '@/lib/analytics'

export default function Home() {
  const headerList = headers()
  const path = headerList.get('x-path') ?? '/'

  after(() => {
    void logPageView({
      path,
      timestamp: Date.now(),
      userAgent: headerList.get('user-agent') ?? undefined,
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by.</p>
    </main>
  )
}

